  "batch4.relations.sync_operation.rule_1": "المبدأ 11: النظام Offline-first يدعم تفريغ طابور IndexedDB بدفعات موثوقة.",
  "batch4.relations.principle_1.title": "Firestore هو Source of Truth للعمليات",
  "batch4.relations.principle_1.desc": "قاعدة بيانات Firestore هي المصدر الأوحد والنهائي للحقيقة لكافة السجلات والعمليات والحالات والمقاييس.",
  "batch4.relations.principle_2.title": "Google Sheets هو Operational/Reporting Projection",
  "batch4.relations.principle_2.desc": "Google Sheets مخصص كإسقاط تقارير وتشغيل لفرق المتابعة دون أي قدرة على تعديل حالة النظام الأساسية.",
  "batch4.relations.principle_3.title": "Google Drive لتخزين ملفات المشروع والتقارير",
  "batch4.relations.principle_3.desc": "تخزين وتنظيم بوالص الشحن، صور تذاكر الموازين، وتقارير الفحص والـ PDF في مجلدات هرمية آمنة.",
  "batch4.relations.principle_4.title": "جميع Business Rules على Server-Side",
  "batch4.relations.principle_4.desc": "جميع شروط العمل والتحقق من الانتقالات والحسابات الضريبية تُنفذ حصراً في بيئة الخادم الموثوقة.",
  "batch4.relations.principle_5.title": "Client لا يقرر Status النهائي",
  "batch4.relations.principle_6.title": "Client لا يحسب القيمة المالية النهائية",
  "batch4.relations.principle_6.desc": "الحسابات المالية، أجور الأطنان، غرامات التأخير، وضريبة 15% ZATCA تُحسب خادومياً بواسطة محرك التسعير.",
  "batch4.relations.principle_7.title": "Client لا يحدد Project Access",
  "batch4.relations.principle_7.desc": "صلاحيات المشاريع تُدار وتُفرض خادومياً عبر Firebase Custom Claims وقواعد Firestore Security Rules.",
  "batch4.relations.principle_8.title": "لا توجد كلمات مرور أو API Secrets داخل Client",
  "batch4.relations.principle_8.desc": "مفاتيح Google Service Accounts والأسرار البرمجية موجودة حصراً في متغيرات بيئة الخادم process.env.",
  "batch4.relations.principle_9.title": "جميع عمليات الكتابة Idempotent",
  "batch4.relations.principle_9.desc": "كل طلب يحمل معرّف UUID ومفتاح Idempotency لضمان تنفيذه مرة واحدة بالضبط ومنع الازدواجية عند إعادة الإرسال.",
  "batch4.relations.principle_10.title": "النظام Multi-Project",
  "batch4.relations.principle_10.desc": "عزل تام للبيانات والسجلات والمستندات على مستوى المشاريع (Tenant Isolation) مع دعم مقاولين متعددي المشاريع.",
  "batch4.relations.principle_11.title": "النظام Offline-First",
  "batch4.relations.principle_11.desc": "الواجهة تعمل بالكامل دون اتصال معتمدة على IndexedDB، وتزامن العمليات تلقائياً فور توفر الشبكة.",
  "batch4.relations.principle_12.title": "جميع التغييرات الحساسة تسجل Audit Log",
  "batch4.relations.principle_12.desc": "سجل تدقيق غير قابل للحذف أو التعديل (Append-Only) يوثق الفاعل، التوقيت، والفروقات لكل تعديل حساس.",
  "batch4.reference.architecture.titleAr": "المعمارية الشاملة والمبادئ",
  "batch4.reference.architecture.summaryAr": "الرؤية المعمارية للمنصة، المبادئ الـ 12 الإلزامية، العلاقات بين الـ 11 كياناً، وهيكلية الطبقات والخدمات.",
  "batch4.reference.data_model.titleAr": "نموذج ومخطط البيانات",
